.darma-loader-tw-chevron-march { display: inline-flex; align-items: center; justify-content: center; gap: calc(var(--loader-size, 80px) * .05); width: var(--loader-size, 80px); height: calc(var(--loader-size, 80px) * .4); }
.darma-loader-tw-chevron-march span { width: calc(var(--loader-size, 80px) * .16); height: calc(var(--loader-size, 80px) * .16); border-top: calc(var(--loader-size, 80px) * .05) solid var(--loader-color, #0ea5e9); border-right: calc(var(--loader-size, 80px) * .05) solid var(--loader-color, #0ea5e9); animation: darma-loader-tw-chevron-march-twMarch calc(var(--loader-speed, 1s) * 1.2) ease-in-out infinite; }
.darma-loader-tw-chevron-march span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .15); }
.darma-loader-tw-chevron-march span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .3); }
@keyframes darma-loader-tw-chevron-march-twMarch { 0%, 100% { opacity: .25; transform: rotate(45deg) translate(0, 0); } 50% { opacity: 1; transform: rotate(45deg) translate(14%, -14%); } }

